using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterCompanions", menuName = "Data/Characters/Companions")]
public class CharacterCompanions : ScriptableObject
{
	[Serializable]
	public class SentinelSetInfo
	{
		public string SetId;

		public List<CompanionData> Sentinels;
	}

	[Serializable]
	public class ModSentinelsSetsInfo
	{
		public string PublishedId;

		public List<SentinelSetInfo> SentinelSetInfosList;

		public ModSentinelsSetsInfo(string publishedId)
		{
			PublishedId = publishedId;
			SentinelSetInfosList = new List<SentinelSetInfo>();
		}
	}

	[Header("Default Companions")]
	public List<CompanionData> DefaultCompanions = new List<CompanionData>();

	[Header("Custom Dice")]
	public List<ModSentinelsSetsInfo> CustomCompanionsList = new List<ModSentinelsSetsInfo>();

	[Header("Editor: Build State")]
	[HorizontalLine(2f, EColor.Gray)]
	public List<CompanionData> BuildCompanions = new List<CompanionData>();
}
